/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountAsciiSharks, type AsciiSharksOptions } from "../../components/ascii-sharks/AsciiSharksEngine.js";
import type { MotionController } from "../../components/ascii-sharks/motion-runtime";

export function AsciiSharks({ options, className }: { options?: AsciiSharksOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountAsciiSharks(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="ascii-sharks" />;
}

